import{_ as e,c as a,o as r,af as l}from"./chunks/framework.4G89wRmb.js";const f=JSON.parse('{"title":"联合主义","description":"","frontmatter":{},"headers":[],"relativePath":"databank/settings/main/rengoism.md","filePath":"databank/settings/main/rengoism.md"}'),n={name:"databank/settings/main/rengoism.md"};function h(s,t,o,i,m,d){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="联合主义" tabindex="-1">联合主义 <a class="header-anchor" href="#联合主义" aria-label="Permalink to “联合主义”">​</a></h1><p>联合主义（Rengoism）是<a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>的官方意识形态与唯一指导思想。该理论由国父<a href="./../people/nambu_kojun.html">南武香淳</a>同志在领导南武人民进行革命斗争的实践中创立，<strong>其由香淳同志奠基的原始理论体系，亦被广泛称为香淳思想</strong>。它是南武世界中社会主义思想的具体体现与独立发展。</p><hr><h2 id="基本情报" tabindex="-1">基本情报 <a class="header-anchor" href="#基本情报" aria-label="Permalink to “基本情报”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>中文名称</strong></td><td style="text-align:left;">联合主义</td></tr><tr><td style="text-align:left;"><strong>英文名称</strong></td><td style="text-align:left;">Rengoism</td></tr><tr><td style="text-align:left;"><strong>别称</strong></td><td style="text-align:left;"><strong>香淳思想</strong>（尤其指香淳同志整体的思想体系）</td></tr><tr><td style="text-align:left;"><strong>创立者</strong></td><td style="text-align:left;"><a href="./../people/nambu_kojun.html">南武香淳</a></td></tr><tr><td style="text-align:left;"><strong>创立时间</strong></td><td style="text-align:left;">1984年起逐步形成</td></tr><tr><td style="text-align:left;"><strong>核心地位</strong></td><td style="text-align:left;"><a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>的立国之本与行动指南</td></tr><tr><td style="text-align:left;"><strong>理论渊源</strong></td><td style="text-align:left;">基于南武国情独立发展的社会主义科学理论</td></tr><tr><td style="text-align:left;"><strong>发展阶段</strong></td><td style="text-align:left;"><strong>香淳思想</strong>、<a href="./kisetsu_line.html">希节路线</a>、<a href="./hachimi_theory.html">八海理论</a></td></tr><tr><td style="text-align:left;"><strong>核心经典</strong></td><td style="text-align:left;">南武香淳著作、<a href="./../others/junshinri_newspaper.html">《纯真理报》</a>社论、全南武进步者大会报告</td></tr></tbody></table><hr><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>联合主义是指导<a href="./nambu_rengoist_party.html">南武联合党</a>和南武人民从革命走向建设的根本理论。其核心目标是通过<strong>人民联合</strong>与<strong>阶级斗争</strong>，彻底推翻资本主义和一切剥削制度，建立并巩固无产阶级专政，最终实现共产主义。</p><p>它并非空想理论，而是一套完整的实践指南，深刻阐述了南武的政治制度（<a href="./comprehensive_leadership.html">全面领导制</a>）、经济制度（<a href="./commonwealth_ownership.html">联合所有制</a>）和文化价值观（<a href="./../others/aesthetics_of_labor.html">劳动美学</a>）。联合主义在其最初形态——即<strong>香淳思想</strong>的指导下，领导南武人民取得了革命胜利。随后，它又通过<a href="./kisetsu_line.html">希节路线</a>和<a href="./hachimi_theory.html">八海理论</a>不断发展，引领国家从经济改革走向科技飞跃，并正朝着建设<a href="./cyber_utopia.html">伟大南武赛博乌托邦</a>的宏伟目标迈进。</p><hr><h2 id="核心主张" tabindex="-1">核心主张 <a class="header-anchor" href="#核心主张" aria-label="Permalink to “核心主张”">​</a></h2><p>联合主义的理论体系建立在以下六大核心主张之上：</p><ol><li><p><strong>人民的联合</strong> 在<a href="./nambu_rengoist_party.html">南武联合党</a>的领导下，团结一切可以团结的进步力量，形成最广泛的革命统一战线，是夺取革命胜利和进行社会主义建设的根本保证。</p></li><li><p><strong><a href="./comprehensive_leadership.html">全面领导制</a></strong> 党、国家与<a href="./nambu_commonwealth.html">南武集团</a>必须在<a href="./supreme_peoples_committee.html">最高人民委员会</a>的统一领导下运作，确保政治、经济和社会发展的高度协同与一致性，是防止官僚主义和权力分散的制度核心。</p></li><li><p><strong>阶级斗争</strong> 在社会主义建成后，资产阶级思想和复辟势力的威胁依然长期存在。必须坚持不懈地进行阶级斗争，巩固无产阶级专政，确保红色江山永不变色。</p></li><li><p><strong>批私斗修</strong> 坚决消灭生产资料私有制，并时刻警惕和斗争任何试图在党内外引入市场化、自由化等背离社会主义道路的修正主义思想。这是保证革命彻底性的关键。</p></li><li><p><strong>发展生产力</strong> 社会主义的优越性必须建立在高度发达的生产力之上。国家必须集中力量发展重工业、尖端科技等关键领域，为满足人民需求和实现最终理想提供坚实的物质基础。</p></li><li><p><strong><a href="./commonwealth_ownership.html">联合所有制</a></strong> 生产资料不应属于任何个人或团体，而应由国家、党和全体人民以“联合”的形式共同拥有。这旨在从根本上消除阶级差异。</p></li></ol><hr><h2 id="理论发展脉络" tabindex="-1">理论发展脉络 <a class="header-anchor" href="#理论发展脉络" aria-label="Permalink to “理论发展脉络”">​</a></h2><p>联合主义是一个不断发展、与时俱进的理论体系，其发展历程主要体现在历代最高人民委员会的理论贡献上。</p><h3 id="香淳思想-奠基理论" tabindex="-1">香淳思想：奠基理论 <a class="header-anchor" href="#香淳思想-奠基理论" aria-label="Permalink to “香淳思想：奠基理论”">​</a></h3><p><strong>香淳思想是联合主义的原始形态与理论内核</strong>，由其创立者<a href="./../people/nambu_kojun.html">南武香淳</a>同志在长期的革命准备和实践中系统性地提出。它完整地构成了联合主义的哲学基础、政治主张和经济构想，是指导<a href="./../others/progressive_revolution.html">南武进步革命</a>取得胜利的根本思想武器。因此，“香淳思想”不仅是联合主义发展的第一阶段，也常常被作为联合主义根本原则的代称，是全体南武人民永恒的精神财富。</p><h3 id="希节路线-实践与发展" tabindex="-1">希节路线：实践与发展 <a class="header-anchor" href="#希节路线-实践与发展" aria-label="Permalink to “希节路线：实践与发展”">​</a></h3><p><a href="./../people/tokishi_kisetsu.html">户岸希节</a>同志在继承香淳思想的基础上，创造性地提出了<a href="./kisetsu_line.html">希节路线</a>。该路线将联合主义的经济构想（如<a href="./commonwealth_ownership.html">联合所有制</a>）转化为具体的国家政策，建立了<a href="./nambu_commonwealth.html">南武集团</a>特色经济模式，并领导了<a href="./../others/whole_nambu_liberation_war.html">争取全南武解放战争</a>的胜利。它是联合主义在社会主义建设初期的伟大实践与发展。</p><h3 id="八海理论-新时代的飞跃" tabindex="-1">八海理论：新时代的飞跃 <a class="header-anchor" href="#八海理论-新时代的飞跃" aria-label="Permalink to “八海理论：新时代的飞跃”">​</a></h3><p>现任总书记<a href="./../people/kawai_hachimi.html">川伊八海</a>同志面对新的时代背景，提出了<a href="./hachimi_theory.html">八海理论</a>。该理论主张将人工智能（<a href="./../others/central_deployment.html">中央部署</a>）与社会主义计划经济深度融合，建设<a href="./cyber_utopia.html">伟大南武赛博乌托邦</a>。这是联合主义在科技革命浪潮下的最新成果，旨在将南武的生产力水平和治理能力提升至前所未有的高度。</p>',22)])])}const p=e(n,[["render",h]]);export{f as __pageData,p as default};
